  const entity=select([]);entity.id='dossier-fact-entity';form.querySelector('.form-pair').before(labeled('Person im Dossier',entity));
  const key=select([['custom',t('Eigene Angabe')],['personName',t('Name')],['birthDate',t('Geburtsdatum')],['birthPlace',t('Geburtsort')]]);key.id='dossier-fact-key';form.querySelector('.form-pair').before(labeled('Art der Angabe',key));
