  const dialog=document.createElement('dialog');dialog.className='rule-dialog dossier-confirm-dialog';const title=node('h3',t('Bevorzugte Angabe bestätigen'));title.id='dossier-confirm-title';dialog.setAttribute('aria-labelledby',title.id);
  const original=user('p',field.source||''),translated=user('p',field.translated||'');dialog.append(title,node('strong',t('Originalangabe')),original,node('strong',t('Dokumentbezogene Übersetzung')),translated,user('p',`${nameOf(d,record.entityId)} · ${t('Dokumentfassung')} ${number(record.version)}`),node('p',t('Diese Bestätigung ändert keine abgeschlossene Übersetzung.')));
  const form=document.createElement('form'),input=document.createElement('input');input.maxLength=300;input.required=true;input.value=field.translated||'';input.dataset.noTranslate='';const check=document.createElement('input');check.type='checkbox';check.required=true;const checkLabel=labeled('Am Original geprüft und ausdrücklich bestätigt',check),error=node('p','','error');error.setAttribute('role','alert');form.append(labeled('Bevorzugte Angabe',input),checkLabel,error);const submit=node('button',t('Bestätigte Angabe speichern'),'primary');submit.type='submit';form.append(submit,action('Abbrechen',async()=>window.TOCRDialogs.close(dialog)));dialog.append(form);
  form.onsubmit=event=>{event.preventDefault();error.textContent='';submit.disabled=true;void(async()=>{try{await localRequest(`/api/dossiers/${encodeURIComponent(d.id)}/facts`,{version:d.version,entityId:record.entityId,key:field.key,label:field.label,value:input.value.trim(),confirmed:check.checked,source:{jobId:record.id,fieldId:field.id,version:record.version}});window.TOCRDialogs.close(dialog);await state.reload();}catch(e){error.textContent=t(e.message);submit.disabled=false;}})();};
  dialog.addEventListener('close',()=>{dialog.remove();if(opener?.isConnected)opener.focus();},{once:true});document.body.append(dialog);window.TOCRDialogs.bind(dialog);window.TOCRDialogs.open(dialog,opener);input.focus();
